    from: 'customers',
    let: {customerId: '$customerId'},
    pipeline: [
        {$match: {$expr: {$eq: ['$_id', '$$customerId']}, status: 'active'}},
        {$project: {_id: 1, name: 1, email: 1}}  // Only needed fields
    ],
    as: 'customer'
}}
```

